 * Why this exists (issue #121; ported from the reference template's
 * scripts/recheck-broken-links.mjs). lychee's `--max-retries` classifies an
 * error by the phase it happened in, and a failure during connect is answered
 * `false` - it is never retried (lycheeverse/lychee#2297). A healthy URL that
 * answers one TCP reset, which is a normal event for a rate-limiting or
 * load-shedding host seen from a CI address range, is therefore reported
 * broken without a single retry, and this repository's links gate fails on it.
 * That is a false positive of exactly the kind issue #121 is about, and the
 * two hosts .lycheeignore already silences for availability rather than
 * correctness (manpages.ubuntu.com, www.gnu.org) show how the alternative fix
 * degrades: a real 404 on those hosts would now be silent forever.
 *
 * PR #132 also failed on two healthy GitHub documentation links answering 503.
 * A temporary server error is not a verdict on whether the document exists:
 * retry 408, 429, 500, 502, 503 and 504 within the same bounded budget. Only an
 * accepted response recovers a URL; a persistent error still fails the gate.
 * Other HTTP failures, including 404, remain final. Fragment URLs also remain
 * final because a HEAD request cannot validate an anchor.
 *
 * Divergence from the template, deliberate
 * ----------------------------------------
 * The template writes `all_recovered=true` whenever every *unanswered* failure
 * recovered, without looking at the answered ones - and its links.yml gates
 * both the Web Archive step and the "Fail if broken links were found" step on
 * `all_recovered != 'true'`. So a report holding one 404 and one connection
 * reset ends green with the 404 in it. Reproduced against the template's own
 * script by experiments/issue-121-template-recheck/, reported upstream as
 * link-foundation/js-ai-driven-development-pipeline-template#184 and
 * link-foundation/rust-ai-driven-development-pipeline-template#170, and
 * not copied: here `all_recovered` means "the whole report was noise", so it
 * is written only when every failure was eligible for retry and all of them
 * recovered.
 *
 * Usage:
 *   node scripts/ci/recheck-broken-links.mjs
 *
 * Environment variables:
 *   LYCHEE_OUTPUT            lychee's markdown report (default: lychee/out.md)
 *   RECOVERED_OUTPUT         where to write the recovered URLs, one per line
 *                            (default: lychee/recovered.txt)
 *   LINKS_WORKFLOW           workflow to read lychee's request options from
 *                            (default: .github/workflows/links.yml)
 *   RECHECK_BUDGET_SECONDS   wall-clock budget for the whole re-check
 *                            (default: 240; expires before the job's 10-minute cap)
 *   RECHECK_WAIT_MS          first wait between rounds, doubling (default: 2000)
 *   BOX_VERBOSE             set to 1 to trace each request (default: off)
 *   GITHUB_OUTPUT            set by GitHub Actions; receives `all_recovered`
 *
 * GitHub Actions outputs:
 *   all_recovered  'true' only when the report held nothing but retryable
 *                  failures, and every URL returns an accepted status now.
 *                  Consumers must test `!= 'true'`, never `== 'false'`: a
 *                  skipped or crashed step leaves the output empty, and only
 *                  the `!=` form fails safe.
 *
 * Exit codes:
 *   0 in every case. This script only ever downgrades a failure, so a bug in
 *   it must not be able to turn a green run red - or a red one green by
 *   crashing before the gate reads its output.
 */

import { appendFileSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

// Read from process.env inside main() only: the assertions in
// experiments/test-issue121-links-recheck.sh import this module, and
// module-scope environment access would run before they can set it.
const BUDGET_SECONDS_DEFAULT = 240;
const INITIAL_WAIT_MS_DEFAULT = 2000;
const REQUEST_TIMEOUT_MS = 30_000;
const USER_AGENT_DEFAULT = 'lychee';
// lychee's documented default --accept list, used when the workflow sets no
// --accept flag. The workflow is parsed rather than duplicated so the re-check
// cannot start judging URLs by a rule the checker no longer uses.
const ACCEPT_DEFAULT = '100..=103,200..=299';
const RETRYABLE_HTTP_STATUSES = new Set([408, 429, 500, 502, 503, 504]);

/**
 * Split a lychee markdown report into per-failure records.
 *
 * A failure is "answered" when the marker is a status code ([404]) or the
 * detail says "Rejected status code": a host replied.
 * Everything else - [ERROR], [TIMEOUT], [UNKNOWN] - is a failure where no host
 * ever answered.
 *
 * @param {string} content - lychee's markdown report
 * @returns {Array<{marker: string, url: string, detail: string, answered: boolean, status: number|null}>}
 */
export function parseLycheeFailures(content) {
  const failures = [];
  const entryPattern =
    /^\s*(?:\*|-)\s+\[([^\]]+)\]\s+<?([^\s>|)]+)>?(?:\s+\(at [^)]*\))?\s*\|?\s*(.*)$/gim;

  let match;
  while ((match = entryPattern.exec(content)) !== null) {
    const marker = match[1].trim();
    const url = match[2].trim().replace(/[.,;!?]+$/, '');
    const detail = match[3].trim();

    if (!url) {
      continue;
    }

    const answered =
      /^\d{3}$/.test(marker) || /rejected status code/i.test(detail);
    const statusMatch = /^\d{3}$/.test(marker)
      ? marker
      : detail.match(/rejected status code:\s*(\d{3})\b/i)?.[1];
    const status = statusMatch ? Number(statusMatch) : null;

    failures.push({ marker, url, detail, answered, status });
  }

  return failures;
}

/**
 * Build an "is this status accepted" predicate from a lychee --accept list
 * such as "100..=103,200..=299,429" (spaces tolerated).
 * @param {string} spec - lychee's --accept list
 * @returns {(status: number) => boolean}
 */
export function parseAcceptRanges(spec) {
  const accepted = new Set();

  for (const part of spec.split(',')) {
    const trimmed = part.trim();

    if (!trimmed) {
      continue;
    }

    const range = trimmed.match(/^(\d+)\.\.=(\d+)$/);

    if (range) {
      for (
        let status = Number(range[1]);
        status <= Number(range[2]);
        status += 1
      ) {
        accepted.add(status);
      }
      continue;
    }

    if (/^\d{3}$/.test(trimmed)) {
      accepted.add(Number(trimmed));
    }
  }

  return (status) => accepted.has(status);
}

/**
 * Read the --accept list and --user-agent the lychee step runs with, so the
 * re-check judges a URL by the rules the checker used.
 * @param {string} workflowText - the links workflow
 * @returns {{accept: string, userAgent: string}}
 */
export function extractLycheeRequestOptions(workflowText) {
  const accept = workflowText.match(/--accept[=\s]+["']?([^\s"']+)["']?/);
  const userAgent = workflowText.match(
    /--user-agent[=\s]+["']?([^\s"']+)["']?/
  );

  return {
    accept: accept ? accept[1] : ACCEPT_DEFAULT,
    userAgent: userAgent ? userAgent[1] : USER_AGENT_DEFAULT,
  };
}

/**
 * Decide whether the run may be called clean.
 *
 * `all_recovered` is read by the workflow as "there is nothing left to fail
 * on", so it has to account for the whole report, not just the part this
 * script re-asked. A final HTTP failure (a 404, a broken fragment) and a
 * failure with no URL to ask (a missing local file) are both still there after
 * a perfect re-check, and neither is this script's to forgive.
 *
 * @param {{finalFailureCount: number, retryableCount: number, recoveredCount: number, stillBrokenCount: number}} counts
 * @returns {boolean}
 */
export function allRecovered(counts) {
  return (
    counts.finalFailureCount === 0 &&
    counts.stillBrokenCount === 0 &&
    counts.retryableCount > 0 &&
    counts.recoveredCount === counts.retryableCount
  );
}

/**
 * Ask every URL again, round by round with a doubling wait, until each one
 * returns an accepted or permanent status, or the budget runs out. Temporary
 * HTTP errors stay pending, just like a URL that keeps refusing to answer.
 *
 * @param {string[]} urls - the URLs eligible for retry
 * @param {{accept: string, userAgent: string, budgetSeconds?: number, initialWaitMs?: number, verbose?: boolean, fetchImpl?: typeof fetch}} options
 * @returns {Promise<{recovered: string[], stillBroken: Array<{url: string, status: number|null, reason: string}>}>}
 */
export async function recheckFailures(urls, options) {
  const accept = parseAcceptRanges(options.accept);
  const fetchImpl = options.fetchImpl || globalThis.fetch;
  const budgetMs = (options.budgetSeconds ?? BUDGET_SECONDS_DEFAULT) * 1000;
  const startedAt = Date.now();
  const initialWaitMs = options.initialWaitMs ?? INITIAL_WAIT_MS_DEFAULT;
  let waitMs = initialWaitMs;
  let round = 0;

  const recovered = [];
  const rejected = [];
  const lastStatus = new Map();
  let pending = [...new Set(urls)];

  while (pending.length > 0 && Date.now() - startedAt < budgetMs) {
    if (round > 0) {
      const elapsed = Date.now() - startedAt;

      // Never start a wait the budget cannot pay for: the point of the budget
      // is that this script finishes well inside the job's cap.
      if (elapsed + waitMs > budgetMs) {
        break;
      }

      await new Promise((resolve) => setTimeout(resolve, waitMs));
      waitMs *= 2;
    }
    round += 1;

    const stillPending = [];

    for (const [index, url] of pending.entries()) {
      const remainingMs = budgetMs - (Date.now() - startedAt);
      if (remainingMs <= 0) {
        stillPending.push(...pending.slice(index));
        break;
      }
      const controller = new AbortController();
      const timeoutId = setTimeout(
        () => controller.abort(),
        Math.min(REQUEST_TIMEOUT_MS, remainingMs)
      );
      let response;

      try {
        response = await fetchImpl(url, {
          method: 'HEAD',
          redirect: 'follow',
          signal: controller.signal,
          headers: { 'user-agent': options.userAgent },
        });
      } catch {
        // Still no answer this round; it stays eligible for the next one.
        if (options.verbose) {
          console.log(`Re-check round ${round}: ${url} did not answer`);
        }
        stillPending.push(url);
        continue;
      } finally {
        clearTimeout(timeoutId);
      }

      lastStatus.set(url, response.status);
      if (options.verbose) {
        console.log(`Re-check round ${round}: ${url} answered ${response.status}`);
      }
      if (accept(response.status)) {
        recovered.push(url);
      } else if (RETRYABLE_HTTP_STATUSES.has(response.status)) {
        stillPending.push(url);
      } else {
        rejected.push({
          url,
          status: response.status,
          reason: `answered ${response.status}, which lychee does not accept`,
        });
      }
    }

    pending = stillPending;
  }

  return {
    recovered,
    stillBroken: [
      ...rejected,
      ...pending.map((url) => ({
        url,
        status: lastStatus.get(url) ?? null,
        reason: lastStatus.has(url)
          ? `HTTP ${lastStatus.get(url)} did not recover within the re-check budget`
          : 'no answer within the re-check budget',
      })),
    ],
  };
}

async function main() {
  const lycheeOutput = process.env.LYCHEE_OUTPUT || 'lychee/out.md';
  const recoveredOutput =
    process.env.RECOVERED_OUTPUT || 'lychee/recovered.txt';
  const workflow =
    process.env.LINKS_WORKFLOW || '.github/workflows/links.yml';
  const options = extractLycheeRequestOptions(readFileSync(workflow, 'utf8'));
  const failures = parseLycheeFailures(readFileSync(lycheeOutput, 'utf8'));

  const canRetry = (failure) =>
    /^https?:\/\//i.test(failure.url) &&
    !new URL(failure.url).hash &&
    (!failure.answered || RETRYABLE_HTTP_STATUSES.has(failure.status));
  // Local files, anchors and permanent HTTP errors cannot be verified by
  // this recovery pass. They stay final even if every other URL recovers.
  const finalFailures = failures.filter((failure) => !canRetry(failure));
  const retryable = [
    ...new Set(failures.filter(canRetry).map((failure) => failure.url)),
  ];

  console.log(
    `Re-check: ${failures.length} lychee failure(s); ` +
      `${finalFailures.length} final, ` +
      `${retryable.length} eligible for retry`
  );

  if (retryable.length === 0) {
    console.log('Re-check: nothing to re-ask.');
    return;
  }

  const result = await recheckFailures(retryable, {
    ...options,
    budgetSeconds: Number(
      process.env.RECHECK_BUDGET_SECONDS || BUDGET_SECONDS_DEFAULT
    ),
    initialWaitMs: Number(
      process.env.RECHECK_WAIT_MS || INITIAL_WAIT_MS_DEFAULT
    ),
    verbose: process.env.BOX_VERBOSE === '1',
  });

  for (const url of result.recovered) {
    console.log(
      `::notice title=Link recovered on re-check::${url} failed temporarily in lychee ` +
        `but answers ${options.accept} now - not a broken link`
    );
  }

  if (result.recovered.length > 0) {
    writeFileSync(recoveredOutput, `${result.recovered.join('\n')}\n`);
  }

  for (const { url, reason } of result.stillBroken) {
    console.log(`Still broken: ${url} - ${reason}`);
  }

  console.log(
    `Re-check finished: ${result.recovered.length} recovered, ` +
      `${result.stillBroken.length} still broken`
  );

  const clean = allRecovered({
    finalFailureCount: finalFailures.length,
    retryableCount: retryable.length,
    recoveredCount: result.recovered.length,
    stillBrokenCount: result.stillBroken.length,
  });

  if (clean) {
    appendFileSync(
      process.env.GITHUB_OUTPUT || '/dev/null',
      'all_recovered=true\n'
    );
    console.log(
      'all_recovered=true: every failure in the report was retryable, ' +
        'and all URLs return an accepted status now.'
    );
    return;
  }

  if (finalFailures.length > 0 && result.stillBroken.length === 0) {
    console.log(
      `all_recovered stays unset: ${finalFailures.length} final failure(s) ` +
        'are still in the report.'
    );
  }
}

// The re-check only downgrades failures, so a crash here must not be able to
// masquerade as a verdict in either direction: exit 0, leave all_recovered
// unset, and let the gate fail on lychee's own result.
const isDirectExecution =
  process.argv[1] &&
  fileURLToPath(import.meta.url) === path.resolve(process.argv[1]);

if (isDirectExecution) {
  main().catch((error) => {
    console.error(`Re-check crashed (treating as no recovery): ${error}`);
    process.exit(0);
  });
}
#!/usr/bin/env bash
#
# Terminal status gate: turn a job that did not succeed into a red run.
#
# Why this exists (issue #121, template best practice "every workflow gets a
# terminal status gate"; see
# https://github.com/link-foundation/js-ai-driven-development-pipeline-template
# scripts/check-pipeline-status.sh, which this is a shell port of).
#
# GitHub derives a run's conclusion from its jobs, and one cancellation
# outranks any number of failures. So a run can contain a job that failed and
# still report itself grey rather than red - and everything that reads the run
# instead of its jobs (the status badge, `gh run list`, the list of recent runs
# quoted in issue #121 itself) then sees "no verdict" where it should see
# "something broke".
#
# That shape is measured here, not hypothesised. Run 34259552358 ("Build and
# Release Docker Image", PR for issue #119, attempt 2) finished with
#
#   run conclusion                     cancelled
#   pr-tests / pr-test / dind-full     failure     (20:34:56Z, on its own)
#   pr-tests / pr-test / full          cancelled   (21:00:52Z, with the run)
#
# It is the only such run in the last 200 (survey in
# dev/log/issues/121/pulls/122/), and it was superseded, so grey was defensible
# *that* time. What makes it worth a gate is that nothing in the colour said so:
# a job cancelled on its own - a `timeout-minutes` overrun, or one of this
# repository's 14 per-job `concurrency: cancel-in-progress` groups firing -
# produces exactly the same grey with no such excuse.
#
# A gate job fixes that because its own conclusion is a job conclusion: when it
# errors, the run is a failure regardless of what else was cancelled.
#
# Hence the two halves. A `failure` is always an error. A `cancelled` is an
# error unless a supersede explains it, and two things have to be true before
# one does: this run is no longer the head of its branch, and the cancelled job
# could actually have been cancelled by that - its effective
# `concurrency.cancel-in-progress` (its own, else the workflow's) is `true`.
# Anything unresolvable - an unreadable head, a workflow file the gate cannot
# find, an expression it cannot evaluate - counts as "not explained": a missed
# supersede costs one noisy error, a missed overrun costs a silent failure.
#
# The second half of that test is issue #123, and it is measured too. Run
# 34366975927 ("Measure Disk Space and Update README", main, 1d9fb3e) carried
#
#   failure  The job has exceeded the maximum execution time of 1h0m0s
#   warning  measure-disk-space. This run is no longer the head of main, so the
#            cancellation reads as a supersede rather than an overrun.
#
# in the same run, and this gate concluded `success`. The job it excused
# declares `timeout-minutes: 60` beside `cancel-in-progress: false` - in the
# workflow's own words it "queues instead of cancelling", so no supersede could
# have touched it and the 1h0m0s overrun was the only thing left. Asking
# whether the *run* was overtaken excuses every job in it, including the ones
# that a supersede cannot reach. scripts/ci/read-job-cancel-in-progress.sh
# answers it per job instead.
#
# The gate job is gated on `!cancelled()`, never `always()` - the repository
# invariant checked by experiments/test-issue115-ci-policy.sh, from hive-mind
# issue #1278. `cancelled()` is a *run*-level predicate: when a whole run is
# cancelled somebody decided to stop it, and repainting that red is a false
# positive, so this job is skipped and the run stays grey. A job cancelled by
# itself does not set it, so those still arrive here.
#
# Usage (from a job with `if: !cancelled()` that `needs:` every other job):
#   NEEDS_JSON='${{ toJSON(needs) }}' \
#   RUN_SHA='${{ github.event.pull_request.head.sha || github.sha }}' \
#   BRANCH_NAME='${{ github.head_ref || github.ref_name }}' \
#     bash scripts/ci/check-pipeline-status.sh
#
# Environment:
#   NEEDS_JSON       required; `toJSON(needs)` from the calling job
#   RUN_SHA          commit this run tests; empty means "assume current"
#   BRANCH_NAME      branch to compare against    (default: main)
#   BRANCH_HEAD_SHA  skips the `git ls-remote` when already known
#   GIT_REMOTE       remote to resolve the head from (default: origin)
#   WORKFLOW_FILE    workflow to read job concurrency from; defaults to the one
#                    GITHUB_WORKFLOW_REF names
#   PIPELINE_STATUS_VERBOSE=1  print the parsed job/result table (default: off)

set -euo pipefail

: "${NEEDS_JSON:?NEEDS_JSON is required (pass toJSON(needs))}"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

BRANCH_NAME="${BRANCH_NAME:-main}"
GIT_REMOTE="${GIT_REMOTE:-origin}"
VERBOSE="${PIPELINE_STATUS_VERBOSE:-0}"

trace() { [ "$VERBOSE" = "1" ] && echo "[pipeline-status] $*" >&2 || true; }

# Answers "has this branch moved past the commit this run tests?". Workflows
# that cancel superseded runs cancel their jobs by design; that must not read
# as an overrun.
run_is_superseded() {
  local head="${BRANCH_HEAD_SHA:-}"

  if [ -z "${RUN_SHA:-}" ]; then
    echo "RUN_SHA is unset; cannot compare this run with the head of ${BRANCH_NAME}; assuming it is current." >&2
    return 1
  fi

  if [ -z "$head" ]; then
    head="$(git ls-remote "$GIT_REMOTE" "refs/heads/${BRANCH_NAME}" 2>/dev/null | awk 'NR == 1 { print $1 }')"
  fi

  if [ -z "$head" ]; then
    echo "Could not resolve the head of ${BRANCH_NAME}; assuming this run is current." >&2
    return 1
  fi

  echo "This run tests ${RUN_SHA}; ${BRANCH_NAME} is at ${head}."
  [ "$head" != "$RUN_SHA" ]
}

# python3 rather than jq: jq is not guaranteed on every runner image this
# repository uses, python3 is (scripts/ci/summarize-measurements.py relies on
# the same assumption).
#
# `cancelled` is selected by name because it is the one result this script
# reasons about. Everything else is selected by *exclusion* - anything that is
# not `success` and not `skipped` counts as a failure - so the gate does not
# depend on knowing the full set of result strings. GitHub documents four for
# `needs.<id>.result` but reports `timed_out` and `action_required` on the jobs
# API, and a spelling this script had never heard of must not be read as
# "nothing wrong".
select_by_result() {
  NEEDS_JSON="$NEEDS_JSON" WANT_RESULT="$1" python3 -c '
import json, os
needs = json.loads(os.environ["NEEDS_JSON"])
want = os.environ["WANT_RESULT"]


def matches(result):
    if want == "cancelled":
        return result == "cancelled"
    return result not in ("success", "skipped", "cancelled")


for name, value in needs.items():
    if matches((value or {}).get("result")):
        print(name)
'
}

# One name per line is what the classification below needs; the comma form is
# only for the annotations, and is built from it.
join_names() {
  local out="" name
  while IFS= read -r name; do
    [ -z "$name" ] && continue
    if [ -z "$out" ]; then out="$name"; else out="$out, $name"; fi
  done <<<"$1"
  printf '%s' "$out"
}

# Which workflow file is this gate running inside? The runner answers it in
# GITHUB_WORKFLOW_REF, as `owner/repo/.github/workflows/<file>@<ref>`. Nothing
# else in the job says so - `github.workflow` is the display name, which is not
# a path and need not be unique.
resolve_workflow_file() {
  local ref path

  if [ -n "${WORKFLOW_FILE:-}" ]; then
    printf '%s' "$WORKFLOW_FILE"
    return 0
  fi

  ref="${GITHUB_WORKFLOW_REF:-}"
  [ -z "$ref" ] && return 1
  ref="${ref%%@*}"
  path="${ref#*/.github/}"
  [ "$path" = "$ref" ] && return 1
  printf '.github/%s' "$path"
}

# Why each cancelled job is or is not explained by a supersede. Prints one
# `<job><TAB><verdict><TAB><reason>` line, verdict `supersede` or `overrun`.
classify_cancellations() {
  local names="$1" superseded="$2"
  local workflow reason name value
  local -A cancel_in_progress=()

  workflow="$(resolve_workflow_file || true)"

  if [ -z "$workflow" ]; then
    reason="the gate could not tell which workflow file it is running inside (GITHUB_WORKFLOW_REF is unset), so it could not read the job's concurrency"
  elif [ ! -f "$workflow" ]; then
    reason="the gate could not read ${workflow} from this checkout, so it could not read the job's concurrency"
  else
    reason=""
    local table=""
    if ! table="$(WORKFLOW_FILE="$workflow" JOB_NAMES="$names" \
      bash "$SCRIPT_DIR/read-job-cancel-in-progress.sh" 2>&1)"; then
      reason="the gate could not read the job concurrency out of ${workflow}: ${table}"
      table=""
    fi
    while IFS=$'\t' read -r name value; do
      [ -z "$name" ] && continue
      cancel_in_progress["$name"]="$value"
    done <<<"$table"
  fi

  while IFS= read -r name; do
    [ -z "$name" ] && continue
    value="${cancel_in_progress[$name]:-unreadable}"
    trace "cancelled job ${name}: cancel-in-progress=${value}, superseded=${superseded}"

    if [ "$superseded" != yes ]; then
      printf '%s\t%s\t%s\n' "$name" overrun \
        "the run is still the head of ${BRANCH_NAME}, so nothing overtook it"
      continue
    fi

    case "$value" in
      true)
        printf '%s\t%s\t%s\n' "$name" supersede \
          "it sets cancel-in-progress: true, so a supersede can cancel it"
        ;;
      false)
        printf '%s\t%s\t%s\n' "$name" overrun \
          "it sets cancel-in-progress: false, so a supersede queues behind it rather than cancelling it"
        ;;
      none)
        printf '%s\t%s\t%s\n' "$name" overrun \
          "it declares no concurrency group, at job or workflow level, so there is nothing for a supersede to cancel it through"
        ;;
      missing)
        printf '%s\t%s\t%s\n' "$name" overrun \
          "${workflow} declares no job by that name, so the gate could not read its concurrency"
        ;;
      *)
        printf '%s\t%s\t%s\n' "$name" overrun \
          "${reason:-the gate could not read its cancel-in-progress, which is an expression rather than a value}"
        ;;
    esac
  done <<<"$names"
}

if [ "$VERBOSE" = "1" ]; then
  trace "needs:"
  NEEDS_JSON="$NEEDS_JSON" python3 -c '
import json, os
for name, value in json.loads(os.environ["NEEDS_JSON"]).items():
    print("  %-40s %s" % (name, (value or {}).get("result")))
' >&2
fi

failed_lines="$(select_by_result not-success)"
cancelled_lines="$(select_by_result cancelled)"

failed="$(join_names "$failed_lines")"
cancelled="$(join_names "$cancelled_lines")"

echo "Failed jobs:    ${failed:-<none>}"
echo "Cancelled jobs: ${cancelled:-<none>}"

status=0

if [ -n "$failed" ]; then
  echo "::error title=Pipeline failed::Failing jobs: ${failed}"
  status=1
fi

if [ -n "$cancelled" ]; then
  superseded=no
  if run_is_superseded; then
    superseded=yes
  fi

  superseded_lines=""
  overrun_lines=""
  while IFS=$'\t' read -r job verdict reason; do
    [ -z "$job" ] && continue
    echo "  ${job}: ${reason}"
    if [ "$verdict" = supersede ]; then
      superseded_lines+="${job}"$'\n'
    else
      overrun_lines+="${job}"$'\n'
    fi
  done < <(classify_cancellations "$cancelled_lines" "$superseded")

  superseded_jobs="$(join_names "$superseded_lines")"
  overrun_jobs="$(join_names "$overrun_lines")"

  if [ -n "$superseded_jobs" ]; then
    echo "::warning title=Cancelled jobs in a superseded run::${superseded_jobs}. This run is no longer the head of ${BRANCH_NAME} and these jobs cancel in progress, so the cancellation reads as a supersede rather than an overrun."
  fi

  if [ -n "$overrun_jobs" ]; then
    echo "::error title=Pipeline has cancelled jobs::${overrun_jobs}. No supersede accounts for these cancellations (see the reasons above). A job killed by 'timeout-minutes' is reported as cancelled, which would otherwise leave the run grey instead of red."
    status=1
  fi
fi

if [ "$status" -eq 0 ]; then
  echo "All required jobs succeeded or were legitimately skipped."
fi

exit "$status"
name: Measure Disk Space and Update README

on:
  push:
    branches:
      - main
    paths:
      - 'scripts/ubuntu-24-server-install.sh'
      - 'scripts/measure-disk-space.sh'
      - 'scripts/update-readme-sizes.sh'
      - 'Dockerfile'
      - '.github/workflows/measure-disk-space.yml'
  # The measurement itself takes ~3 hours and pushes to main, so it cannot run
  # on a pull request. What CAN run on a pull request is everything that decides
  # whether the measurement is going to work at all — and it has to, because
  # this workflow only ever ran after the merge. Run 33972074753 (main, commit
  # 42be663) is the case in point: `NODE_MAJOR: unbound variable` was
  # introduced, reviewed and merged without a single job ever executing the
  # changed script (issue #115).
  pull_request:
    types: [opened, synchronize, reopened]
    paths:
      - 'scripts/ubuntu-24-server-install.sh'
      - 'scripts/measure-disk-space.sh'
      - 'scripts/update-readme-sizes.sh'
      - 'ubuntu/24.04/common.sh'
      - 'data/disk-space-measurements.json'
      - '.github/workflows/measure-disk-space.yml'
      # The preflight and validation jobs, which are what a pull request can
      # run here, are the only place these three are executed at all. They are
      # deliberately absent from the push filter above: editing a validator
      # should re-run the validation, not spend three hours measuring disk.
      - 'scripts/ci/extract-quoted-heredoc.sh'
      - 'scripts/ci/validate-measurements.py'
      - 'scripts/ci/summarize-measurements.py'
  # Allow manual trigger
  workflow_dispatch:
    inputs:
      force_update:
        description: 'Force update README even if no changes detected'
        required: false
        type: boolean
        default: false
      verbose:
        description: 'Trace what the measurement script resolves, generates and hands to the box user (BOX_VERBOSE=1)'
        required: false
        type: boolean
        default: false

# Least-privilege default; the measurement job escalates to `contents: write`
# for its push. The validation job never needs more than a read.
permissions:
  contents: read

env:
  # actions/checkout's first act is `git init`, and a git with no configured
  # `init.defaultBranch` answers it with a thirteen-line advice block - "Using
  # 'master' as the name for the initial branch... this default branch name will
  # change" - at the top of every job log. 19 checkouts in the runs issue #121
  # lists printed 247 lines of it, in jobs where nothing was wrong. No step can
  # fix it, because it is printed before the first step of ours runs; git reads
  # configuration from the environment too, and the environment is there from
  # the start. Ported from the js template, which carries the same three lines
  # with the same reasoning.
  GIT_CONFIG_COUNT: '1'
  GIT_CONFIG_KEY_0: ini…nch
  GIT_CONFIG_VALUE_0: main

jobs:
  # Fast pre-merge gate. Nothing here installs anything, so it finishes in
  # under a minute and can run on every pull request that touches the scripts.
  validate:
    name: Validate measurement scripts
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    concurrency:
      group: check-${{ github.workflow }}-${{ github.ref }}-validate
      cancel-in-progress: true
    steps:
      - name: Checkout repository
        uses: actions/checkout@v6
        with:
          persist-credentials: false

      # A pull_request checkout is GitHub's merge preview, computed when the
      # pull request was last synchronised and never recomputed as main moves.
      # Merge the base branch first, so this job reports on what merging would
      # actually produce (issue #115, best practice #7).
      - name: Simulate a fresh merge with the base branch
        uses: ./.github/actions/simulate-fresh-merge

      - name: Syntax-check the scripts
        run: |
          for f in scripts/measure-disk-space.sh scripts/ubuntu-24-server-install.sh scripts/update-readme-sizes.sh; do
            echo "bash -n $f"
            bash -n "$f"
          done

      # The generated script is written from a quoted heredoc, so `bash -n` on
      # the parent says nothing about it. Extract it and check it separately.
      #
      # The extraction used to be an inline awk pattern that hardcoded the
      # spacing of the opener (`cat > /tmp/box-measure.sh <<`). shfmt then
      # reformatted the script to `cat >/tmp/box-measure.sh <<'EOF_BOX'` and the
      # pattern matched nothing, failing this job on every push (issue #115,
      # RC-22). The extraction now matches what bash parses rather than how the
      # line happens to be formatted, and says which of "no opener", "no
      # terminator" and "empty body" it hit.
      - name: Syntax-check the generated box-user script
        run: |
          bash scripts/ci/extract-quoted-heredoc.sh \
            scripts/measure-disk-space.sh EOF_BOX > /tmp/generated-measure.sh
          echo "extracted $(wc -l < /tmp/generated-measure.sh) lines"
          bash -n /tmp/generated-measure.sh

      - name: Check for variables leaking out of quoted heredocs
        run: bash scripts/ci/check-heredoc-vars.sh

      - name: Regression tests for issue #115
        run: bash experiments/test-issue115-heredoc-unbound-vars.sh

      # Argument handling is the other half of what broke: the documented
      # no-argument invocation used to abort on `$1: unbound variable`.
      - name: Check the command line interface
        run: |
          ./scripts/measure-disk-space.sh --help > /dev/null
          if ./scripts/measure-disk-space.sh --not-an-option 2>/dev/null; then
            echo "::error::an unknown option must be rejected"; exit 1
          fi

      # The committed measurements feed the README table; a malformed file
      # would only be noticed three hours into the next measurement run.
      - name: Validate the committed measurements
        run: python3 scripts/ci/validate-measurements.py data/disk-space-measurements.json

  measure-disk-space:
    name: Measure Component Disk Space
    # Pull requests stop at `validate`; measuring installs every toolchain on a
    # bare runner and ends in a push to main.
    if: github.event_name != 'pull_request'
    runs-on: ubuntu-24.04
    # 180 was "3 hours max for full installation measurement" - a number nobody
    # had checked against a run. Every successful run of this job in the
    # repository's history finished inside 23.3 minutes, the slowest of them in
    # February (dev/log/issues/121/pulls/122/analysis/); 60 leaves more than
    # twice that and still bounds a hang at an hour instead of three (issue
    # #121, docs/CI-TIMEOUT-BUDGETS.md).
    timeout-minutes: 60
    # This job commits to main. Cancelling it mid-`git push` is worse than
    # letting a superseded run finish, so it queues instead of cancelling —
    # unlike the pre-merge checks above.
    concurrency:
      group: measure-disk-space-${{ github.ref }}
      cancel-in-progress: false

    # pull-requests: write is for the fallback path in
    # scripts/release/git-push-with-retry.sh only (issue #121).
    permissions:
      contents: write
      pull-requests: write

    env:
      # Off by default. `workflow_dispatch` can turn it on without editing the
      # workflow, which is the whole point of having it (issue #115).
      BOX_VERBOSE: ${{ inputs.verbose && '1' || '0' }}

    steps:
      - name: Checkout repository
        uses: actions/checkout@v6
        with:
      - name: Run disk space measurement
        id: measure
        run: |
          set -o pipefail
          echo "=== Starting disk space measurement ==="

          # Make script executable
          chmod +x scripts/measure-disk-space.sh

          # sudo resets the environment (env_reset), so BOX_VERBOSE has to be
          # handed over explicitly rather than merely exported here.
          # pipefail ensures script failures propagate through tee.
          # The budget wraps the measurement, not the pipeline: `tee` has to
          # stay outside it so the log survives an overrun, and `pipefail` above
          # still carries the wrapper's exit status - 124 when it runs out of
          # budget (issue #121, docs/CI-TIMEOUT-BUDGETS.md).
          bash scripts/ci/run-with-budget-warning.sh 2400 "disk space measurement" \
            sudo env "BOX_VERBOSE=$BOX_VERBOSE" ./scripts/measure-disk-space.sh \
            --json-output data/disk-space-measurements.json 2>&1 | tee measurement.log

          echo "=== Measurement complete ==="

          # Check if JSON was created
          if [ -f data/disk-space-measurements.json ]; then
            echo "json_created=true" >> "$GITHUB_OUTPUT"
            echo ""
            echo "=== Measurements JSON ==="
            cat data/disk-space-measurements.json
          else
            echo "json_created=false" >> "$GITHUB_OUTPUT"
            echo "::error::JSON file was not created"
            exit 1
          fi

      - name: Update README with component sizes
        if: steps.measure.outputs.json_created == 'true'
        env:
            echo "No changes detected"
          else
            echo "has_changes=true" >> "$GITHUB_OUTPUT"
            echo "Changes detected:"
            git diff --stat README.md data/disk-space-measurements.json 2>/dev/null || true
          fi

      # The thresholds used to be compared with `[ -lt ]`, but total_size_mb is
      # a float ("7286.0"), so that test never once evaluated: bash printed
      # "integer expression expected", returned 2, and the `||` fell through to
      # "valid". A measurement reporting 5 MB with a plausible component count
      # would have been committed as good. The checks live in a script now, so
      # they are testable and shared with the pull request gate (issue #115).
      #
      # `if ... then valid=true else valid=false` was wrong in the same way the
      # `[ -lt ]` test was, one level up: the validator documents 0 = valid,
      # 1 = invalid, 2 = usage error, and argparse exits 2 as well - so a
      # SyntaxError, a renamed flag or a missing file all read as "these
      # measurements are invalid" and quietly threw away three hours of work
      # with the job green (issue #121). Only 1 means invalid. Anything else
      # means the question was not answered, which is an error, not a verdict.
      - name: Validate measurements
        id: validate
        run: |
          set +e
          python3 scripts/ci/validate-measurements.py data/disk-space-measurements.json
          rc=$?
          set -e
          case "$rc" in
            0)
              echo "valid=true" >> "$GITHUB_OUTPUT"
              ;;
            1)
              echo "valid=false" >> "$GITHUB_OUTPUT"
              echo "::warning::The measurements are invalid; nothing will be committed."
              ;;
            *)
              echo "::error title=Measurement validation could not run::validate-measurements.py exited $rc, which is neither valid (0) nor invalid (1). The measurement is not being discarded on the strength of an answer nobody got."
              exit 1
              ;;
          esac

      - name: Commit and push changes
        if: steps.changes.outputs.has_changes == 'true' && steps.validate.outputs.valid == 'true'
        env:
          # Only read on the fallback path, when a repository rule declines the
          # direct push and the commit has to arrive as a pull request.
          GH_TOKEN: ${{ github.token }}
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"

          git add README.md data/disk-space-measurements.json

          # Create commit message with summary
          TOTAL_SIZE=$(python3 -c "import json; print(json.load(open('data/disk-space-measurements.json'))['total_size_mb'])" 2>/dev/null || echo "unknown")

          # Guarded like every other commit in this repository: the subject is
          # generated here, but the diffstat and file list git prints with it
          # are not, and one exception is how the invariant stops holding
          # (issue #123).
          bash scripts/ci/run-with-commands-stopped.sh git commit -m "chore: update component disk space measurements (${TOTAL_SIZE}MB total)"

          # This job runs for about 18 minutes before it pushes, which is a wide
          # window for the release workflow to land a version bump. A single
          # pull-rebase closes most of it but not the seconds between the
          # rebase and the push, and it never retries; the helper rebases and
          # retries, and answers a repository-rule rejection with a pull
          # request rather than a rebase that cannot satisfy it (issue #121,
          # and see docs/case-studies/issue-51 for the original race).
          # Measurement data (README.md, data/) and version bumps (VERSION)
          # touch different files, so the rebase resolves cleanly.
          bash scripts/release/git-push-with-retry.sh origin main "disk-space-measurements"

          echo "Changes committed and pushed successfully"

      # Deliberately NOT gated on has_changes. It used to be, which meant a
      # measurement that was invalid AND identical to the committed one passed
      # the workflow silently — the failure mode that keeps a broken number in
      # the README for as long as it stays broken.
      - name: Fail on invalid measurements
        if: steps.validate.outputs.valid != 'true'
        run: |
          echo "::error::Invalid measurements detected. Not committing to prevent data corruption."
          echo "Please investigate the measurement logs and fix the underlying issue."
          exit 1

      # Always upload, especially on failure: measurement.log is the only record
      # of what the three-hour run did, and a plain step without `if:` is
      # skipped as soon as anything above it fails — which is exactly when the
      # log is wanted (issue #115).
      #
      # And require it, rather than warning about its absence. `warn` made the
      # one thing that must not happen — the only record of the run not being
      # kept — into a line in the log of the run whose record is missing. The
      # reason it was `warn` is that `!cancelled()` also holds when the job
      # failed before the measurement, so the upload is gated on the measuring
      # step having run instead: `tee measurement.log` above creates the file
      # the moment that step starts, so from then on at least one of these two
      # paths exists and an empty match means the evidence was lost. Written in
      # the positive form because the `steps` context holds only steps that
      # "have an `id` specified and have already run" (GitHub, "Contexts"), so a
      # step that never started has no entry and `!= 'skipped'` would be true of
      # that empty value (issue #123).
      - name: Upload measurement artifacts
        if: ${{ !cancelled() && (steps.measure.outcome == 'success' || steps.measure.outcome == 'failure') }}
        uses: actions/upload-artifact@v7
        with:
          name: disk-space-measurements
          path: |
            data/disk-space-measurements.json
            measurement.log
          retention-days: 30
          if-no-files-found: error

      - name: Summary
        if: ${{ !cancelled() }}

