# Reproduce PR 132's GitHub 503 failures without accessing the network.
# Set RECHECK_TEST_SCRIPT to an earlier script to verify the reproducer fails.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."

