  validateFailureReport(report, process.env.LYCHEE_EXIT_CODE);
  const failures = parseLycheeFailures(report);

  const canRetry = (failure) =>
    /^https?:\/\//i.test(failure.url) &&
    URL.canParse(failure.url) &&
    !failure.url.includes('#') &&
